from pathlib import Path
import csv, io, json, re, subprocess
from itertools import combinations

out = Path('evidence')
out.mkdir(exist_ok=True)
for p in sorted(Path('.').glob('*.pdf')):
    subprocess.run(['pdftotext', '-layout', str(p), str(out / (p.stem + '.txt'))], check=True)

def number(s):
    return int(s.replace(',', ''))

data = {}
for edition, enc in [(4, 'utf-8-sig'), (6, 'cp932'), (7, 'cp932')]:
    filename = f'R{edition}_CA.csv'
    rows = list(csv.reader(io.StringIO(Path(filename).read_text(encoding=enc))))
    years = {i: 2018 + int(s[2:-1]) for i, s in enumerate(rows[2]) if re.fullmatch('令和[０-９]+年', s)}
    values = {}
    for i, year in years.items():
        values[year] = {'total': number(rows[3][i]), 'completed': number(rows[4][i]), 'attempted': number(rows[5][i]),
                        'cells': [f'{chr(65+i)}{r}' for r in (4,5,6)]}
    data[f'R{edition}'] = values
# R5 has no CSV: parse the year header and the three rows from the PDF text.
lines = (out / 'R5_資料_修正版.txt').read_text().split('\\n')
header = next(i for i,l in enumerate(lines) if '令和元年' in l and '令和５年' in l and i+1 < len(lines) and '総' in lines[i+1])
nums = [[number(x) for x in re.findall(r'\\d[\\d,]*', lines[header+k])] for k in (1,2,3)]
data['R5'] = {y: dict(zip(['total','completed','attempted'], [a[i] for a in nums])) for i,y in enumerate(range(2019,2024))}
results = {'data': data, 'Q1_equal': data['R6'][2022]['completed'] == data['R7'][2022]['completed'],
           'Q2_totals': {e: v[2021]['total'] for e,v in sorted(data.items())},
           'sums': {e: {y: v[y]['completed']+v[y]['attempted'] for y in (2020,2021) if y in v} for e,v in sorted(data.items())},
           'post2022_common_year_differences': []}
for (a,av),(b,bv) in combinations(sorted(data.items()),2):
    for y in sorted(av.keys() & bv.keys()):
        if y >= 2022:
            for key in ('completed','attempted'):
                if av[y][key] "'!= bv[y][key]:
                    results['"'post2022_common_year_differences'].append([a,b,y,key,av[y][key],bv[y][key]])
(out/'results.json').write_text(json.dumps(results,ensure_ascii=False,indent=2)+'\\n')
# Preserve line numbers based strictly on LF, retaining PDF form feeds on the same line.
for p in sorted(out.glob('*.txt')):
    if p.name.endswith('.numbered.txt'):
        continue
    (out/(p.stem+'.numbered.txt')).write_text(''.join(f'{i:4d}\\t{line}\\n' for i,line in enumerate(p.read_text().split('\\n'),1)))
print(json.dumps(results,ensure_ascii=False,indent=2))
